 float a[68],ac[512],as[64],b[68],bc[512],bs[64],c[9]={0};for(int frame=0;frame<360;++frame){c[0]=frame>90&&frame<150?1.f:0.f;c[2]=frame==250?1.f:0.f;CHECK(step(old,1.f/60,c,9)==0&&dango_belt_step(fresh,1.f/60,c,9)==0);CHECK(read(old,a,68,ac,512,as,64)==0&&dango_belt_read(fresh,b,68,bc,512,bs,64)==0);CHECK(memcmp(a,b,sizeof a)==0&&memcmp(ac,bc,sizeof ac)==0&&memcmp(as,bs,sizeof as)==0);}CHECK(destroy(old)==0&&dango_belt_destroy(fresh)==0);CHECK(FreeLibrary(module));printf("preserved pre-calibration DLL versus new default: all 644 floats bit-identical for 360 frames at 60Hz PASS\n");
